package com.fitpulse.model.dto; import com.fitpulse.model.enums.ContentStatus; import jakarta.validation.constraints.*; import java.math.BigDecimal;
public class GymForm { private Long cityId; @Size(max=100,message = "{ui.city.names.can.contain.up.to.100}") private String newCityName; public String getNewCityName(){return newCityName;} public void setNewCityName(String value){newCityName=value;} @AssertTrue(message = "{ui.select.a.city.or.enter.a.new.2}") public boolean isCitySelected(){return cityId!=null||(newCityName!=null&&!newCityName.isBlank());} @NotBlank(message = "{ui.fill.in.this.required.field}") @Size(max=150,message = "{ui.this.field.allows.up.to.max.characters}") private String name; @Size(max=3000,message = "{ui.this.field.allows.up.to.max.characters}") private String description; @Size(max=300,message = "{ui.this.field.allows.up.to.max.characters}") private String address; @DecimalMin(value="-90",message = "{ui.latitude.must.be.between.90.and.90}") @DecimalMax(value="90",message = "{ui.latitude.must.be.between.90.and.90}") @Digits(integer=3,fraction=6,message = "{ui.coordinates.can.have.up.to.six.decimal}") private BigDecimal latitude; @DecimalMin(value="-180",message = "{ui.longitude.must.be.between.180.and.180}") @DecimalMax(value="180",message = "{ui.longitude.must.be.between.180.and.180}") @Digits(integer=3,fraction=6,message = "{ui.coordinates.can.have.up.to.six.decimal}") private BigDecimal longitude; @Size(max=50,message = "{ui.this.field.allows.up.to.max.characters}") private String phone; @Size(max=500,message = "{ui.this.field.allows.up.to.max.characters}") private String websiteUrl; @Size(max=1000,message = "{ui.this.field.allows.up.to.max.characters}") private String openingHours; @Size(max=1500,message = "{ui.this.field.allows.up.to.max.characters}") private String services; @Size(max=1000,message = "{ui.this.field.allows.up.to.max.characters}") private String priceInfo; @NotNull(message = "{ui.fill.in.this.required.field}") private ContentStatus status=ContentStatus.DRAFT; public Long getCityId(){return cityId;} public void setCityId(Long v){cityId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public BigDecimal getLatitude(){return latitude;} public void setLatitude(BigDecimal v){latitude=v;} public BigDecimal getLongitude(){return longitude;} public void setLongitude(BigDecimal v){longitude=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getWebsiteUrl(){return websiteUrl;} public void setWebsiteUrl(String v){websiteUrl=v;} public String getOpeningHours(){return openingHours;} public void setOpeningHours(String v){openingHours=v;} public String getServices(){return services;} public void setServices(String v){services=v;} public String getPriceInfo(){return priceInfo;} public void setPriceInfo(String v){priceInfo=v;} public ContentStatus getStatus(){return status;} public void setStatus(ContentStatus v){status=v;}  @AssertTrue(message = "{ui.enter.a.valid.http.or.https.website}") public boolean isWebsiteUrlValid(){return com.fitpulse.service.GymContent.webUrl(websiteUrl);} @AssertTrue(message = "{ui.enter.both.coordinates.or.leave.both.blank}") public boolean isCoordinatesValid(){return (latitude==null)==(longitude==null);} }
